  "CAFE CASINO": { region: "UFM", regionId: "7b25844b-cafa-41b4-a1bf-b05da0b9aeb6", brandName: "CafeCasino", brandCode: "CFC", bucket: "Default", territory: "DEFAULT", pageUrl: "https://www.cafecasino.lv/" },
  "IGN": {
