  },
  "JOE FORTUNE": { region: "AUS", regionId: "5ad12f9e-94dc-11e8-9eb6-529269fb1459", brandName: "JoeFortune", brandCode: "JFN", bucket: "Default", territory: "DEFAULT", pageUrl: "https://www.joefortune.win/" },
  "OZOON": { region: "CAN", regionId: "879370bf-0480-458b-a3ad-11e7138eac30", brandName: "Bodog", brandCode: "BDG", bucket: "Canada", territory: "CANADA", pageUrl: "https://www.ozoon.eu/" },
  "RBL": { region: "UFM", regionId: "070f3d79-d2a9-4747-9fe7-a2fa74a39272", brandName: "Lucky Rebel", brandCode: "RBL", bucket: "Default", territory: "DEFAULT", pageUrl: "https://www.luckyrebel.la/" },
  "SLOTS": {
    "UFM": { regionId: "660dae1a-b7cd-11e7-abc4-cec278b6b50a", brandName: "Slots LV", brandCode: "SLLV", bucket: "Default", territory: "DEFAULT", pageUrl: "https://www.slots.lv/" },
