  }
};

let resolved = jiraBrand ? mappingTable[jiraBrand] : null;

if (resolved && !resolved.brandCode) {
  resolved = jiraRegion ? resolved[jiraRegion] : null;
}

return {
  sessionId: $('CMS & MM Login').item.json.sessionId,
  name: $('Naming Conventions API').item.json.name,
  slug: $('Naming Conventions API').item.json.slug,
  ...(resolved || { error: "No mapping found", jiraBrand, jiraRegion })
};

