parameters.jsCode:
const brand = $('OSN Static Fields Mapping').item.json.brandCode;
const region = $('OSN Static Fields Mapping').item.json.region || "UFM";
const csvContent = `AUDIENCE_CODE,PLAYER_ID\n123456,TEST_PLAYER_UUID_MOCK`;

return {
  helpers: {
    binary: {
      createFromText: true
    }
  },
  json: {
    fileName: `${brand}-${region}.csv`
  },
  binary: {
    data: {
      data: btoa(csvContent),
      mimeType: 'text/csv',
      fileName: `${brand}-${region}.csv`
    }
  }
};

